module bank;

struct Account { balance: Int }

enum Op {
    Deposit { amount: Int },
    Withdraw { amount: Int }
}

fn apply(in acc: Account, in op: Op) -> Account {
    match op {
        Op::Deposit { amount } => Account { balance: acc.balance + amount },
        Op::Withdraw { amount } => {
            if acc.balance >= amount {
                Account { balance: acc.balance - amount }
            } else {
                acc
            }
        }
    }
}

fn run(in ops: [Op; 4]) -> Int {
    var acc = Account { balance: 0 };
    for op in ops {
        acc = apply(acc, op);
    }
    acc.balance
}

fn main() -> Int {
    let ops: [Op; 4] = [
        Op::Deposit { amount: 100 },
        Op::Withdraw { amount: 50 },
        Op::Withdraw { amount: 100 },
        Op::Deposit { amount: 200 }
    ];
    run(ops)
}

