module stats;

pub fn rle(in s: Str) -> String {
    var result = String;
    var index = 0;
    var current_byte = 0;
    var count = 0;

    if std::str::count(s, "") == 0 {
        return result;
    }

    while index < std::str::count(s, "") {
        current_byte = std::str::byte_at(s, index);
        count = 1;
        var next_index = index + 1;
        while next_index < std::str::count(s, "") {
            if std::str::byte_at(s, next_index) == current_byte {
                count = count + 1;
                next_index = next_index + 1;
            } else {
                break;
            }
        }
        result = result.push_int(current_byte);
        result = result.push_int(count);
        index = next_index;
    }
    return result;
}

spec rle {
    then rle("") == "";
    then rle("a") == "a1";
    then rle("aaabcc") == "a3b1c2";
